:root {
  /* Colors */
  --color-linen-canvas: #fefdfc;
  --color-paper-white: #ffffff;
  --color-cream-tile: #f9f7f6;
  --color-mint-wash: #f4fbf7;
  --color-keylime-wash: #f6faeb;
  --color-peach-wash: #fff6f0;
  --color-charcoal-glass: #25221ed4;
  --color-ink: #25221e;
  --color-graphite-caption: #25221ea8;
  --color-ash-caption: #25221e7d;
  --color-stone-border: #25221e2e;
  --color-mist-fill: #25221e12;
  --color-ember-signal: #e34432;

  /* Typography — Font Families */
  --font-graphik: "Graphik", "Inter Tight", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-caecilia: "Caecilia", "Zilla Slab", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.5;
  --tracking-small: 0.3px;
  --text-caption: 13.5px;
  --leading-caption: 1.35;
  --tracking-caption: 0.135px;
  --text-body-sm: 14.5px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0.18px;
  --text-body: 15.5px;
  --leading-body: 1.35;
  --tracking-body: 0.155px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.75;
  --tracking-body-lg: 0.09px;
  --text-subheading: 20.5px;
  --leading-subheading: 1.6;
  --tracking-subheading: 0px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.28;
  --tracking-heading-sm: 0px;
  --text-heading: 38px;
  --leading-heading: 1.28;
  --tracking-heading: -0.19px;
  --text-heading-lg: 44px;
  --leading-heading-lg: 1.15;
  --tracking-heading-lg: -0.44px;
  --text-display: 55px;
  --leading-display: 1.15;
  --tracking-display: -0.55px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium-2: 475;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-semibold-2: 625;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-9: 9px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-128: 128px;

  /* Layout */
  --layout-page-max-width: 1312px;
  --layout-section-gap: 128px;
  --layout-card-padding: 24px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-xl: 13px;
  --radius-2xl: 15px;

  /* Named Radii */
  --radius-cards: 15px;
  --radius-buttons: 15px;
  --radius-images: 15px;
  --radius-nav: 13px;
  --radius-smallCards: 10px;
  --radius-alertBanners: 10px;
  --radius-smallElements: 8px;
  --radius-inputs: 8px;
  --radius-tags: 6px;
  --radius-badges: 6px;

  /* Shadows */
  --shadow-subtle: rgba(37, 34, 30, 0.04) 0px 1px 0px 0px;
  --shadow-md: rgba(42, 29, 48, 0.06) 0px 1px 19px 0px, rgba(250, 232, 214, 0.6) 0px 0px 48px 0px;
  --shadow-lg: rgba(37, 34, 30, 0.07) 0px 14px 19px -9px, rgba(37, 34, 30, 0.18) 0px 10px 48px 0px;

  /* Surfaces */
  --surface-linen-canvas: #fefdfc;
  --surface-cream-tile: #f9f7f6;
  --surface-peach-wash: #fff6f0;
  --surface-paper-white: #ffffff;
  --surface-charcoal-glass: #25221ed4;
}

